class Solution:
    def findSubtreeSizes(self, parent: List[int], s: str) -> List[int]:
        n = len(parent)
        ch = [[] for _ in range(n)]
        for i in range(1, n): ch[parent[i]].append(i)
        stacks = [[] for _ in range(26)]
        np = [0] * n; order = []
        st = [(0, True)]
        while st:
            x, enter = st.pop()
            c = ord(s[x]) - 97
            if enter:
                stacks[c].append(x)
                np[x] = stacks[c][-2] if len(stacks[c]) > 1 else parent[x]
                order.append(x)
                st.append((x, False))
                for y in ch[x]: st.append((y, True))
            else:
                stacks[c].pop()
        sz = [1] * n
        for x in reversed(order):
            if x: sz[np[x]] += sz[x]
        return sz

