class Solution {
public:
    vector<int> findSubtreeSizes(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<int>> ch(n);
        for (int i = 1; i < n; i++) ch[parent[i]].push_back(i);
        vector<array<int,0>> _;
        vector<vector<int>> st(26);
        vector<int> np(n), order;
        vector<pair<int,bool>> stk{{0, true}};
        while (!stk.empty()) {
            auto [x, enter] = stk.back(); stk.pop_back();
            int c = s[x] - 'a';
            if (enter) {
                st[c].push_back(x);
                np[x] = st[c].size() > 1 ? st[c][st[c].size() - 2] : parent[x];
                order.push_back(x);
                stk.push_back({x, false});
                for (int y : ch[x]) stk.push_back({y, true});
            } else st[c].pop_back();
        }
        vector<int> sz(n, 1);
        for (int i = n - 1; i >= 0; i--) {
            int x = order[i];
            if (x) sz[np[x]] += sz[x];
        }
        return sz;
    }
};

