class Solution {
    public int[] findSubtreeSizes(int[] parent, String s) {
        int n = parent.length;
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < n; i++) ch.get(parent[i]).add(i);
        Deque<Integer>[] st = new ArrayDeque[26];
        for (int c = 0; c < 26; c++) st[c] = new ArrayDeque<>();
        int[] np = new int[n]; List<Integer> order = new ArrayList<>();
        Deque<int[]> stk = new ArrayDeque<>(); stk.push(new int[]{0, 1});
        while (!stk.isEmpty()) {
            int[] top = stk.pop(); int x = top[0]; boolean enter = top[1] == 1;
            int c = s.charAt(x) - 'a';
            if (enter) {
                st[c].push(x);
                np[x] = st[c].size() > 1 ? (int)st[c].toArray()[1] : parent[x];
                order.add(x);
                stk.push(new int[]{x, 0});
                for (int y : ch.get(x)) stk.push(new int[]{y, 1});
            } else st[c].pop();
        }
        int[] sz = new int[n]; Arrays.fill(sz, 1);
        for (int i = n - 1; i >= 0; i--) {
            int x = order.get(i);
            if (x != 0) sz[np[x]] += sz[x];
        }
        return sz;
    }
}

