var findSubtreeSizes = function(parent, s) {
    const n = parent.length;
    const ch = Array.from({length: n}, () => []);
    for (let i = 1; i < n; i++) ch[parent[i]].push(i);
    const st = Array.from({length: 26}, () => []);
    const np = Array(n), order = [];
    const stk = [[0, true]];
    while (stk.length) {
        const [x, enter] = stk.pop();
        const c = s.charCodeAt(x) - 97;
        if (enter) {
            st[c].push(x);
            np[x] = st[c].length > 1 ? st[c][st[c].length - 2] : parent[x];
            order.push(x);
            stk.push([x, false]);
            for (const y of ch[x]) stk.push([y, true]);
        } else st[c].pop();
    }
    const sz = Array(n).fill(1);
    for (let i = n - 1; i >= 0; i--) {
        const x = order[i];
        if (x) sz[np[x]] += sz[x];
    }
    return sz;
};
